import {LightningElement} from 'lwc'; import {getLocationService,getContactsService} from 'lightning/mobileCapabilities'; export default class Probe extends LightningElement {result='pending'; connectedCallback(){let rows={};for(const [n,f] of [['location',getLocationService],['contacts',getContactsService]]) {try{let x=f(); rows[n]={type:typeof f,available:x.isAvailable()};}catch(e){rows[n]={error:String(e)};}}this.result=JSON.stringify(rows);} }